class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: Cosmos provider no longer supports HasIndex (throws at runtime in 9.0).
        // Indexes are managed by Cosmos DB itself; remove the HasIndex call.
        // (was: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);)

        // Breaking change 2: Discriminator property renamed from "Discriminator" to "$type" in 9.0.
        // To remain compatible with existing documents that use "Discriminator", explicitly configure it.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 3: Id property format changed from "EntityType|Key" to just "Key" in 9.0.
        // To remain compatible with existing documents that use "Blog|<key>" ids, use a value generator
        // or set HasValueGenerator to None and manage ids yourself. The simplest backward-compatible
        // fix is to opt back in to the legacy id format with an id factory.
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // Opt back into the legacy "Discriminator|Key" id format for backward compatibility.
        // Without this, 9.0 generates ids as just the key value, breaking existing documents.
        // NOTE: Replace with your actual connection string / endpoint configuration.
        base.OnConfiguring(optionsBuilder);
    }
}
