using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // BREAKING CHANGE 1 – HasIndex removed for Cosmos provider (throws in 9.0).
        // Cosmos manages indexes server-side; remove the call entirely.
        // was: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);

        // BREAKING CHANGE 2 – Discriminator property renamed from "Discriminator" to "$type".
        // Existing documents use "Discriminator", so explicitly keep the old name.
        modelBuilder.Entity<Blog>()
            .HasDiscriminator<string>("Discriminator");

        // BREAKING CHANGE 3 – Id format changed from "EntityType|Key" to just "Key".
        // Existing documents have id = "Blog|1". Tell EF Core 9 to keep generating
        // ids in the legacy "Discriminator|Key" format so reads/writes stay compatible.
        modelBuilder.Entity<Blog>()
            .Property(b => b.Id)
            .HasValueGenerator<LegacyCosmosIdGenerator>();
    }
}

/// <summary>
/// Reproduces the EF Core 8 Cosmos id format: "EntityTypeName|KeyValue".
/// Required for backward compatibility with existing documents.
/// </summary>
class LegacyCosmosIdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;

    public override string Next(Microsoft.EntityFrameworkCore.ChangeTracking.EntityEntry entry)
    {
        var entityType = entry.Metadata.ShortName();   // e.g. "Blog"
        var key = entry.Property("Id").CurrentValue?.ToString();
        return $"{entityType}|{key}";
    }
}

class Blog { public string Id { get; set; } public string Name { get; set; } }

